cd /scr/wurgaft/auto-psych/agent_trees/d6b6238b22d937a5/repo/_runs/cell_1/experiment2/model_loop/iter_0/candidate_4_repair_1/scratch; cat > res.py <<'EOF'
import csv,numpy as np,sys
from collections import defaultdict
rows=list(csv.DictReader(open('../../../responses.csv')));p=np.load(sys.argv[1])
y=np.array([int(r['rating']) for r in rows]);ll=y*np.log(p)+(1-y)*np.log(1-p)
print(ll.sum())
g=defaultdict(list)
for i,r in enumerate(rows): g[r['number_set']].append(i)
def ent(v):
  t=defaultdict(list)
  for i in v: t[(rows[i]['target'])].append(y[i])
  return sum(len(a)*(np.mean(a)*np.log(np.mean(a)+1e-9)+(1-np.mean(a))*np.log(1-np.mean(a)+1e-9)) for a in t.values())
res=sorted(((ll[v].sum()-ent(v),k,len(v),y[v].mean(),p[v].mean()) for k,v in g.items()))
for x in res[:15]: print("%.1f %-14s n=%d y=%.2f p=%.2f"%x)
for s in [x[1] for x in res[:int(sys.argv[2])]]:
  t=defaultdict(list)
  for i in g[s]: t[int(rows[i]['target'])].append(i)
  print(s,[(k,round(y[t[k]].mean(),1),round(p[t[k][0]],2)) for k in sorted(t)])
EOF
